R=[
 record('lustrous-lunarian-sustainable-city','c0560','Land of the Lustrous — Lunarian sustainable city','Land of the Lustrous','Active human-descended Lunarians in the maintained lunar city',['manga','book'],
 scope('Manga and its volume-11 companion booklet','The established lunar city before the final universal release','Active Lunarians as an explicit human-descendant person proxy',['Terrestrial Gems and Admirabilis as one economy','The anime as depicting the same later institutions','Inanimate objects as additional residents'],proxy=True),
 'The companion booklet describes a city designed for continuing material sustainability, using synthetic materials and recycling. Residents can survive without taking jobs, so their access is meaningfully separated from necessary employment. The guarantee estimate is strong within this city, although an unofficial translation and the absence of a detailed entitlement charter justify a broad interval. Their unusual bodies reduce nutritional needs; that fact alone is not the evidence for inclusion—the maintained technological city and its stated survival-independent provision are.\n\nLunarians are active human descendants, explicitly used here as a person proxy. Their leadership is concentrated around Aechmea rather than identified as an autonomous AI or equal resident ownership. The government retains jobs for purpose and mental health, overlapping with the article’s zero-variant theme without creating a second copy of the economy. Useful restaurant, research and military activity remains work. A normal work schedule and optional employment therefore do not supply an all-person nonworking percentage, which remains unresolved.',
 {'guarantees':-0.75,'control':0.1,'nonworking':None},
 {'guarantees':assessment(-0.75,[-0.95,-0.25],'medium','The booklet explicitly separates survival from jobs and describes a sustainable synthetic-material city; coverage details remain limited.',l),
  'control':assessment(0.1,[0,0.35],'low','Concentrated Lunarian leadership is a human-descendant elite analogy, not an AI sovereign or verified democratic productive ownership.',l),
  'nonworking':assessment(None,None,'low','Many useful jobs persist; a typical schedule and freedom from necessary employment are not a population participation census.',l)},
 1,l,[evidence('The sustainable lunar city permits survival without a job while retaining purpose-giving employment.',l,'Companion booklet: city/government and work-life sections; human-descendant context','unofficial_translation_and_secondary_reference')],
 ['Unofficial incomplete companion-booklet translation; no claim to reading the full book.', 'The human-descendant person proxy and manga-era scope are explicit.', 'Optional useful work still counts; participation remains unresolved.', 'Purpose-giving jobs overlap with the zero theme, but do not create an additional society.']),
 record('franxx-plantation-adult-provision','c0568','Darling in the Franxx — Plantation adult residents','Darling in the Franxx','Technologically sustained adult civilian households under APE',['anime'],
 scope('2018 television anime','Established Plantation life around episode 10, before the later collapse','Living adult civilian residents',['Child pilots as nonworking adults','APE officials as typical residents','The post-collapse agrarian community','The manga’s different continuity']),
 'Plantation adults receive continuing technological bodily support rather than surviving through ordinary household employment. Episode 10 shows artificial nourishment and domestic medical machinery, alongside a partner absorbed in a pleasure device. This supports a protected adult enclave with a relatively strong material floor, although its dependence on the Plantation infrastructure makes that security conditional. Immortality by itself would not establish post-work access; the depicted continuing support arrangement is the relevant evidence.\n\nAPE concentrates authority above residents, who are not shown collectively controlling their productive infrastructure. Its alien masters are not automatically an autonomous AI, so the control point uses the concentrated non-AI elite position by analogy. The adult population is deliberately narrow: human child pilots perform dangerous defense work outside this denominator, and the arrangement cannot stand for all humanity. A high, low-confidence nonworking estimate follows the described passive civilian life, with a wide allowance for useful care, administration and other activity. It is an editorial estimate rather than a canonical census, and it does not apply after the system collapses.',
 {'guarantees':-0.55,'control':0.05,'nonworking':0.9},
 {'guarantees':assessment(-0.55,[-0.9,0.25],'low','Adult households receive bodily support and machine care, but infrastructure dependence and unknown withdrawal conditions qualify access.',f),
  'control':assessment(0.05,[0,0.2],'low','APE concentrates nonresident authority; its alien identity does not make it an AI. Concentrated non-AI rule is an explicit analogy.',f),
  'nonworking':assessment(0.9,[0.6,1],'low','Passive civilian life supports a broad directional estimate, not a census. Useful adult work counts and child military labor is disclosed outside the scoped cohort.',f)},
 1,f,[evidence('Adult households use artificial nourishment and medical machinery, while child pilots provide protection.',f,'Episode 10 adult encounter and series population distinction','secondary_episode_reference_and_commentary')],
 ['Adult enclave only: dependent child defense labor remains visible.', 'APE’s ultimate rulers are alien, not assumed AI.', 'No universal rights charter or participation census was found.', 'Manga and post-collapse society are excluded.'])
]
R[0]['employment_preservation']={'retained_artificial_jobs':True,'basis':'The city supports survival without employment while the government maintains jobs to provide purpose; useful voluntary activity still counts as work.','source_ids':['src-b72-lunarian-culture'],'does_not_create_additional_society':True}
